INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(1, 1, '平安京が遷都された年はいつですか？', '710年', '794年', '784年', '857年', 1, '794年（延暦13年）に桓武天皇によって平安京に遷都されました。「鳴くよ（794）ウグイス平安京」という語呂合わせで知られています。710年は奈良への遷都（平城京）、784年は長岡京への遷都の年です。', 1, false),
(1, 1, '平安京の設計思想「四神相応」において、北方を守るとされる神獣はどれですか？', '青龍', '白虎', '朱雀', '玄武', 3, '四神相応では、北を「玄武」、東を「青龍」、西を「白虎」、南を「朱雀」が守るとされます。京都では北の船岡山が玄武、東の鴨川が青龍、西の山陰道が白虎、南の巨椋池が朱雀に対応しています。', 1, false),
(1, 1, '四神相応において、南方を守るとされる神獣はどれですか？', '青龍', '白虎', '朱雀', '玄武', 2, '南を守るのは「朱雀（すざく）」です。平安京では南の開けた地（巨椋池や現在の城南宮付近）が朱雀に対応しています。京都には「朱雀大路」や「朱雀院」など朱雀にちなんだ地名が残っています。', 1, false),
(1, 1, '平安京を造営した天皇は誰ですか？', '光仁天皇', '桓武天皇', '嵯峨天皇', '聖武天皇', 1, '平安京を造営したのは桓武天皇（かんむてんのう）です。784年にまず長岡京に遷都しましたが、水害・造営責任者の暗殺などの問題が続いたため、794年に平安京へ改めて遷都しました。', 1, false),
(1, 1, '平安京の設計で手本とした中国の都市はどこですか？', '洛陽', '長安', '南京', '北京', 1, '平安京は中国・唐の都「長安」（現在の西安）を模して設計されました。碁盤の目状の街路や、北に宮城を置く配置などが長安にならっています。「洛中」という言葉も長安の別名「洛陽」を意識したものです。', 2, false),
(1, 1, '平安京を南北に走る中央大路の名称はどれですか？', '大宮通', '朱雀大路', '烏丸通', '室町通', 1, '平安京の中央を南北に走る大路は「朱雀大路（すざくおおじ）」で、幅は約85メートルもありました。現在の千本通がその跡とされています。この大路によって都が東（左京）と西（右京）に分けられました。', 1, false),
(1, 1, '平安京において天皇の居所があった場所（大内裏）はどの方角にありましたか？', '南端中央', '東端', '北端中央', '西端', 2, '大内裏（天皇の居所）は平安京の北端中央に位置していました。これは中国の都城設計の慣例で、君主が北に座して南を向く（南面）という思想に基づきます。「北闕（ほっけつ）」とも呼ばれました。', 2, false),
(1, 1, '「四神相応の地」として平安京が選ばれた理由に含まれないものはどれですか？', '東に川がある（青龍）', '西に道がある（白虎）', '海に面している（玄武）', '南が開けている（朱雀）', 2, '四神相応の条件は、東に川（青龍→鴨川）・西に道（白虎→山陰道）・北に山（玄武→船岡山）・南が開けている（朱雀→巨椋池）ことです。「海に面している」は四神相応の条件に含まれません。', 2, false),
(1, 1, '現在の京都御所は、平安時代の内裏と比べてどの方向に位置していますか？', '西（右京側）', '南', '東（左京側）', '同じ場所', 2, '現在の京都御所（上京区）は、平安時代の大内裏よりも東側（左京側）に移っています。平安時代の大内裏は現在の千本丸太町付近にありましたが、たびたびの火災などを経て東側に移動し、室町時代頃に現在地に定着しました。', 3, false),
(1, 1, '平安京の南端に設けられた都の正門の名称はどれですか？', '朱雀門', '羅城門', '応天門', '建春門', 1, '平安京の南端中央に設けられた正門は「羅城門（らじょうもん）」です。芥川龍之介の小説「羅生門」の舞台としても有名で、現在の唐橋羅城門跡付近に碑が立てられています。朱雀門は大内裏南面の門です。', 2, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(1, 2, '渡月橋の名前の由来として正しいものはどれですか？', '橋が月の形をしているから', '亀山上皇が「くまなき月の渡るに似る」と詠んだことから', '橋の上から月がよく見えるから', '月の出る方角に向いているから', 1, '渡月橋の名は、鎌倉時代の亀山上皇（後嵯峨天皇の皇子）が「くまなき月の渡るに似る」と詠んだことに由来するといわれています。現在の橋は昭和9年（1934年）に竣工したもので、橋桁はコンクリートで手すりが木製です。', 1, false),
(1, 2, '嵐山の渡月橋の下を流れる川の名前はどれですか？', '宇治川', '鴨川', '桂川（大堰川）', '木津川', 2, '渡月橋の下を流れるのは「桂川（大堰川/保津川）」です。上流の亀岡付近では「保津川」、嵐山付近では「大堰川（おおいがわ）」とも呼ばれ、淀川に合流します。保津川下りで有名な渓谷を流れてきた川です。', 1, false),
(1, 2, '嵐山で世界遺産に登録されている禅宗寺院はどれですか？', '清凉寺（嵯峨釈迦堂）', '天龍寺', '常寂光寺', '野宮神社', 1, '天龍寺（てんりゅうじ）は「古都京都の文化財」の一つとしてユネスコ世界文化遺産に登録されています。足利尊氏が後醍醐天皇の菩提を弔うために創建した臨済宗の禅寺で、夢窓疎石作の曹源池庭園が名高いです。', 1, false),
(1, 2, '天龍寺の庭園（曹源池庭園）を作庭した人物は誰ですか？', '小堀遠州', '夢窓疎石', '重森三玲', '善阿弥', 1, '天龍寺の曹源池庭園（そうげんちていえん）は、臨済宗の高僧・夢窓疎石（むそうそせき）が作庭しました。嵐山を借景とした池泉回遊式庭園で、国の特別名勝に指定されています。', 2, false),
(1, 2, '嵐山で有名な「竹林の道」はどの区間にありますか？', '渡月橋〜天龍寺', '天龍寺北門〜野宮神社付近', '常寂光寺〜二尊院', '大河内山荘〜落柿舎', 1, '嵐山の竹林の道（竹林の小径）は、天龍寺の北門から野宮神社付近にかけての区間にあります。孟宗竹が両側にそびえる幻想的な光景で、京都を代表する観光スポットとして国内外から多くの観光客が訪れます。', 1, false),
(1, 2, '嵐山の「保津川下り」の出発地点はどこですか？', '嵐山（渡月橋付近）', '亀岡', '南丹市', '福知山', 1, '保津川下りは亀岡（かめおか）を出発地として、約16kmの渓谷を約2時間かけて嵐山まで下る川遊びです。急流・奇岩が続く雄大な自然の中を船で下るコースで、四季を通じて人気の観光アクティビティです。', 1, false),
(1, 2, '嵐山の野宮神社（ののみやじんじゃ）のご利益として知られるものはどれですか？', '商売繁盛・五穀豊穣', '縁結び・子宝・学業成就', '交通安全・旅行安全', '厄除け・病気平癒', 1, '野宮神社は縁結び・子宝・学業成就のご利益で知られます。源氏物語にも登場し、かつて斎宮（さいぐう）が伊勢神宮へ赴く前に身を清めた聖地として知られています。境内の黒木鳥居は日本最古の形式の鳥居です。', 1, false),
(1, 2, '嵐山の標高はおよそ何メートルですか？', '約131メートル', '約381メートル', '約681メートル', '約981メートル', 1, '嵐山の標高は約381メートルです。「嵐山」という名は嵐のような強い風が吹くことに由来するとも、嵐（嵐山の嵐は嵐峰の意）と呼ばれた山の名ともいわれています。亀山とも呼ばれます。', 2, false),
(1, 2, '嵐山周辺の観光鉄道「嵯峨野トロッコ列車」の正式な運営会社名はどれですか？', '西日本旅客鉄道（JR西日本）', '嵯峨野観光鉄道', '京都丹後鉄道', '京福電気鉄道', 1, '嵯峨野観光鉄道（株）が運営するトロッコ列車は、JR山陰本線の旧線を利用した観光専用鉄道です。トロッコ嵯峨駅からトロッコ亀岡駅まで約7.3kmを走り、保津峡の絶景を楽しめます。', 2, false),
(1, 2, '嵐山の桜や紅葉の名所「大河内山荘（おおこうちさんそう）」は誰の山荘でしたか？', '大正・昭和の時代劇俳優、大河内傳次郎', '江戸時代の大名', '明治の政治家', '平安時代の貴族', 0, '大河内山荘は昭和の時代劇俳優・大河内傳次郎（おおこうちでんじろう）が生涯をかけて造り上げた回遊式庭園です。嵐山・嵯峨野の竹林の中にあり、京都市街や比叡山を望む絶景で知られます。', 3, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(1, 3, '嵯峨野観光鉄道（トロッコ列車）の起点駅はどこですか？', 'トロッコ亀岡駅', 'トロッコ保津峡駅', 'トロッコ嵯峨駅', 'トロッコ嵐山駅', 2, '嵯峨野観光鉄道のトロッコ列車はトロッコ嵯峨駅（京都市右京区）を起点として、トロッコ亀岡駅（亀岡市）を終点とします。全長約7.3kmを約25分かけて走行します。', 1, false),
(1, 3, '嵯峨野観光鉄道が走る路線はもともと何線の旧線を利用していますか？', '山陰本線（嵯峨野線）', '山陽本線', '湖西線', '舞鶴線', 0, '嵯峨野観光鉄道はJR山陰本線（現在の嵯峨野線）の旧線を利用した観光専用鉄道です。1989年（平成元年）に山陰本線が電化・複線化された際に旧線が廃線となり、1991年（平成3年）に観光鉄道として再開業しました。', 2, false),
(1, 3, '嵯峨野観光鉄道トロッコ列車の途中駅「トロッコ保津峡駅」の特徴として正しいものはどれですか？', '大きな観光施設が隣接している', '車でしかアクセスできない', '川の真上（橋の上）に駅がある', '地下駅である', 2, 'トロッコ保津峡駅は保津川に架かる橋の上に造られた珍しい構造の駅で、近くに民家や道路がなく、列車かトレッキングでしかアクセスできない「秘境駅」です。保津峡の渓谷美を間近で楽しめるスポットです。', 2, false),
(1, 3, '嵯峨野観光鉄道の終点「トロッコ亀岡駅」はどこにありますか？', '亀岡市保津町', '亀岡市亀岡町', '亀岡市曽我部町', '亀岡市千代川町', 0, 'トロッコ亀岡駅は亀岡市保津町にあります。ここから保津川下りの乗船場まで徒歩圏内で、保津川下り（嵐山まで下る川下り）とトロッコ列車を組み合わせる観光コースが人気です。', 3, false),
(1, 3, '嵯峨野観光鉄道の開業年はいつですか？', '1971年（昭和46年）', '1981年（昭和56年）', '1991年（平成3年）', '2001年（平成13年）', 2, '嵯峨野観光鉄道は1991年（平成3年）4月27日に開業しました。JR山陰本線の新線（電化・複線）完成に伴い旧線が廃線となった後、観光鉄道として再生されました。現在も年間約100万人以上が利用します。', 2, false),
(1, 3, 'トロッコ列車が走る保津峡（ほづきょう）の渓谷美の特徴として正しいものはどれですか？', '砂漠のような地形', '奇岩・急流・深い谷が続く渓谷', '広大な平野が広がる', '海岸線に沿った景観', 1, '保津峡は京都府亀岡市から京都市嵐山まで続く保津川の渓谷で、奇岩・急流・深い谷が連続する雄大な自然の景観が特徴です。春の桜・新緑、秋の紅葉が特に美しく、年間を通じて多くの観光客が訪れます。', 1, false),
(1, 3, '嵯峨野観光鉄道の車両の特徴として正しいものはどれですか？', '全席グリーン席の豪華列車', '窓のないオープン型客車', 'リニアモーター式の高速列車', '2階建て車両', 1, '嵯峨野観光鉄道のトロッコ列車には窓のないオープン型客車（ザ・リッチ号とも呼ばれる）が連結されており、風を感じながら保津峡の景色を楽しめます。このオープン車両が最も人気が高く、予約が取りにくい車両です。', 1, false),
(1, 3, '嵯峨野観光鉄道のトロッコ嵯峨駅に隣接するJRの駅はどれですか？', 'JR花園駅', 'JR太秦駅', 'JR嵯峨嵐山駅', 'JR馬堀駅', 2, 'トロッコ嵯峨駅はJR嵄峨嵐山駅に隣接しています。JR嵯峨嵐山駅はJR山陰本線（嵯峨野線）の駅で、嵐山・嵯峨野観光の主要アクセス拠点です。', 1, false),
(1, 3, '嵯峨野観光鉄道では季節や特別なイベント時に特別列車が運行されることがあります。秋の風物詩として知られるイベントはどれですか？', '花火列車', '紅葉ライトアップ夜間特別列車', '雪景色を楽しむ特別列車', 'ホタル観賞列車', 1, '嵯峨野観光鉄道では秋の紅葉シーズンに、ライトアップされた保津峡の紅葉を楽しむ夜間特別列車を運行することがあります。幻想的な夜の渓谷美が楽しめるとして人気です。', 2, false),
(1, 3, 'トロッコ列車から眺める保津峡の景色で、特に秋に美しいとされるものはどれですか？', '雪化粧した山並み', '桜の花', '紅葉（もみじ）', 'ひまわり畑', 2, '保津峡は秋の紅葉が特に有名で、トロッコ列車の窓から紅葉した山々の景色を楽しめます。赤・橙・黄に染まった山肌と保津川の清流の組み合わせは「錦繍の渓谷」とも呼ばれる絶景です。', 1, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(2, 4, '清水寺の「清水の舞台」はどのような建築工法で作られていますか？', '鉄筋コンクリート造', '釘を一本も使わない懸造り（かけづくり）', '石積み工法', '現代の免震構造', 1, '清水の舞台は「懸造り（かけづくり）」という伝統工法で建てられており、139本のケヤキの柱で支えられています。釘を一本も使わず、木材を組み合わせるだけで作られており、高さは約13メートルあります。', 1, false),
(2, 4, '清水寺の本尊は何ですか？', '阿弥陀如来', '薬師如来', '十一面千手観世音菩薩', '釈迦如来', 2, '清水寺の本尊は「十一面千手観世音菩薩（じゅういちめんせんじゅかんぜおんぼさつ）」です。秘仏として通常は非公開で、33年に一度の御本尊特別公開の際にのみ拝観できます。', 1, false),
(2, 4, '清水寺が世界遺産に登録されたのはいつですか？', '1987年', '1994年', '2000年', '2010年', 1, '清水寺は1994年（平成6年）に「古都京都の文化財」の一つとしてユネスコ世界文化遺産に登録されました。京都・宇治・大津にある17の資産が一括して登録されています。', 1, false),
(2, 4, '清水寺の境内にある「音羽の滝」は何本の流れから構成されていますか？', '1本', '2本', '3本', '5本', 2, '音羽の滝は3本の流れから構成されており、それぞれ延命長寿・恋愛成就・学業上達のご利益があるとされています。ただし欲張って3つすべてを飲むと効果がなくなるという言い伝えもあります。', 1, false),
(2, 4, '清水寺を開いたとされる僧と、寺の整備に貢献した武将の組み合わせとして正しいのはどれですか？', '空海と坂上田村麻呂', '行基と坂上田村麻呂', '延鎮（賢心）と坂上田村麻呂', '最澄と藤原道長', 2, '清水寺は778年に延鎮（えんちん、のちに賢心とも）が音羽の滝のほとりに草庵を結んだことに始まるとされます。その後、坂上田村麻呂が鹿を追って霊地を訪れ延鎮と出会い、自らの妻や鹿を供養するために堂宇を整備したと伝わります。', 2, false),
(2, 4, '清水寺の三重塔は何色ですか？', '白', '黒', '朱（赤）', '金色', 2, '清水寺の三重塔は朱色（朱塗り）で塗られており、高さ約31メートルで国内最大級の三重塔の一つです。1632年（江戸時代）に再建されたもので、重要文化財に指定されています。', 1, false),
(2, 4, '清水寺の宗派はどれですか？', '真言宗', '天台宗', '臨済宗', '北法相宗', 3, '清水寺は「北法相宗（ほっそうしゅう）」の大本山です。法相宗は唯識思想に基づく奈良仏教の宗派で、清水寺は現在、北法相宗として独立した大本山となっています。', 3, false),
(2, 4, '清水寺参道にある有名な石畳の坂道「産寧坂（三年坂）」について正しいものはどれですか？', '坂が急すぎて危険なため「三年坂」と呼ばれる', '転ぶと三年以内に死ぬという言い伝えがある', '三年間かけて整備した坂道', '徳川三代の時代に作られた坂道', 1, '産寧坂（さんねいざか・三年坂）には「転ぶと三年以内に死ぬ」という言い伝えがあります。また、「産寧」は子安塔への安産祈願（産寧り）に由来するとも言われます。二寧坂（二年坂）と合わせて京都の代表的な観光スポットです。', 1, false),
(2, 4, '清水寺の成就院（じょうじゅいん）の庭園は何の名所として知られていますか？', '梅の名所', '月の庭（月見の名所）', '桜の名所', '牡丹の名所', 1, '清水寺の塔頭・成就院の庭園は「月の庭」とも呼ばれ、小堀遠州の作と伝わる江戸時代の名園です。鑑賞の名所として秋に特別公開されることがあります。', 3, false),
(2, 4, '「清水の舞台から飛び降りる」という慣用句の意味はどれですか？', '無謀な挑戦をすること', '大きな決意・決断をすること', '失恋の絶望から立ち直ること', '財産をすべて投じること', 1, '「清水の舞台から飛び降りる」という慣用句は「重大な決意を固めて物事に臨む」という意味です。高さ約13メートルの舞台から飛び降りるほどの覚悟で決断するという喩えで、江戸時代には実際に願掛けで飛び降りた記録も残っています。', 1, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(2, 5, '伏見稲荷大社の「千本鳥居」で有名な鳥居の色は何色ですか？', '白', '金', '朱（赤）', '黒', 2, '伏見稲荷大社の千本鳥居は鮮やかな朱色（朱塗り）の鳥居がトンネル状に並ぶ光景で有名です。稲荷山の参道に数千本もの朱鳥居が立ち並び、京都を代表する絶景として外国人観光客にも人気No.1の観光スポットです。', 1, false),
(2, 5, '伏見稲荷大社の主祭神はどれですか？', '天照大神（あまてらすおおみかみ）', '稲荷大神（うかのみたまのかみなど）', '八幡大神（はちまんのおおかみ）', '素戔嗚尊（すさのおのみこと）', 1, '伏見稲荷大社の主祭神は「稲荷大神（いなりのおおかみ）」で、宇迦之御魂神・佐田彦大神・大宮能売大神・田中大神・四大神の五柱を総称します。五穀豊穣・商売繁盛・産業興隆のご利益で知られます。', 2, false),
(2, 5, '伏見稲荷大社が創建されたのはいつですか？', '奈良時代（711年）', '平安時代（794年）', '鎌倉時代（1185年）', '室町時代（1336年）', 0, '伏見稲荷大社は和銅4年（711年）に創建されたと伝えられ、全国約30,000社の稲荷神社の総本社です。平安遷都（794年）よりも古い歴史を持ち、京都で最も歴史ある神社の一つです。', 2, false),
(2, 5, '伏見稲荷大社の神使（神様のお使い）として知られる動物はどれですか？', '鹿', '鶴', '狐（キツネ）', 'ウサギ', 2, '稲荷神社では狐（キツネ）が稲荷大神のお使い（神使）として知られています。境内に狐の石像が置かれているのはこのためです。稲荷信仰では白狐が稲荷神の化身・使者とされています。', 1, false),
(2, 5, '伏見稲荷大社の本殿背後にある「稲荷山」の標高はおよそ何メートルですか？', '約133メートル', '約233メートル', '約333メートル', '約533メートル', 1, '稲荷山の標高は約233メートルです。山頂（一ノ峰）まで参道が続いており、全山を歩くと約4km・所要約2〜3時間かかります。山中には無数の塚・社があります。', 2, false),
(2, 5, '奥社奉拝所（奥の院）にある「おもかる石」とは何ですか？', '願い事が叶うと持ち上がる伝説の岩', '石灯籠の空輪（丸い部分）で、持ち上げて重さで願いの成否を占うもの', '病気平癒に効くとされる霊石', '古代の碑文が刻まれた石', 1, '「おもかる石」は奥社奉拝所に一対置かれた石灯籠の上部（空輪）のことです。持ち上げる前に願い事をして、思ったより軽ければ願いが叶い、重ければ叶いにくいとされる占いの石として人気です。', 2, false),
(2, 5, '伏見稲荷大社の「千本鳥居」を奉納しているのは主にどのような人々ですか？', '皇族・公家のみ', '商売繁盛や願いの成就を祈る個人・企業', '神職・氏子の関係者のみ', '外国人観光客', 1, '千本鳥居は商売繁盛・家内安全などの願い事の成就を祈って、または願いが叶った御礼として個人や企業が奉納したものです。鳥居には奉納者の名前と奉納年が刻まれています。江戸時代頃から盛んになりました。', 1, false),
(2, 5, '伏見稲荷大社で毎年2月に行われる最重要神事は何ですか？', '節分大祭', '初午大祭（はつうまたいさい）', '例大祭', '鎮花祭', 1, '「初午大祭（はつうまたいさい）」は2月の最初の午の日に行われる伏見稲荷大社の重要な神事で、711年に稲荷大神が稲荷山に鎮座されたことを記念する祭りです。全国の稲荷神社でも初午には祭りが行われます。', 2, false),
(2, 5, '伏見稲荷大社は世界遺産「古都京都の文化財」に含まれていますか？', '含まれている（1994年登録）', '含まれている（2000年登録）', '含まれていない', '申請中', 2, '伏見稲荷大社は「古都京都の文化財」として世界遺産に登録されている17の資産には含まれていません。しかし、外国人観光客から「日本で最も行きたい場所」として高い人気を誇ります。', 3, false),
(2, 5, '伏見稲荷大社の鳥居が朱色である主な理由として適切なものはどれですか？', '徳川幕府が朱色を義務付けたから', '赤は魔除け・生命力の色とされ、木材の防腐効果もあるから', '中国の影響で縁起の良い色とされているから', '太陽神の色である金色の代わりだから', 1, '鳥居が朱色（赤）なのは、古来より赤が「魔除けの色」「生命力の色」とされていたためです。また、ベンガラ（酸化鉄）を使った朱塗りには木材の防腐効果もあります。稲荷神社では特に朱色が好まれてきました。', 2, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(3, 6, '「京野菜」として認定・ブランド化されているカブの一種で、千枚漬けの材料として有名なものはどれですか？', '聖護院大根', '聖護院かぶ', '賀茂なす', '万願寺とうがらし', 1, '千枚漬けの材料として使われるのは「聖護院かぶ（しょうごいんかぶ）」という大きな丸カブです。薄く切って昆布・酢・砂糖・塩で漬けた千枚漬けは京都の代表的な漬物で、冬が旬の京野菜です。', 1, false),
(3, 6, '京野菜「賀茂なす（かもなす）」の特徴として正しいのはどれですか？', '細長くて皮が固い', '白い色をしている', 'まん丸くてずっしりと大きい', '辛みが強い', 2, '賀茂なすは上賀茂地区で栽培される伝統京野菜で、まん丸くずっしりと大きく育つのが特徴です。皮が薄く果肉が柔らかく、みそ田楽（田楽焼き）に使われることで有名です。', 1, false),
(3, 6, '「万願寺とうがらし（まんがんじとうがらし）」について正しいものはどれですか？', '非常に辛いとうがらし', '大きくて甘みのある肉厚のとうがらし', '黄色いとうがらし', '小さくて種が多いとうがらし', 1, '万願寺とうがらしは舞鶴市万願寺地区原産の京野菜で、大きくて肉厚・甘みがあり、「とうがらしの王様」とも呼ばれます。丹波の伏見とうがらしとカリフォルニアワンダーの交配種とされ、昭和初期に誕生しました。', 2, false),
(3, 6, '京都の伝統野菜「九条ねぎ（くじょうねぎ）」はどのような特徴がありますか？', '白い部分（白ねぎ）が長い', '葉の緑色が濃く、葉と葉の間から蜜（ぬめり）が出る軟白ねぎ', '非常に細い万能ねぎ', '球根が大きい玉ねぎの一種', 1, '九条ねぎは葉ねぎ（青ねぎ）の一種で、葉が柔らかく甘みがあり、葉と葉の間から粘り気のある汁（ぬめり）が出るのが特徴です。京都の鍋料理・うどんなどに欠かせない京野菜で、九条（東九条）地区が発祥とされます。', 2, false),
(3, 6, '京都の三大漬物として知られる「千枚漬け・すぐき漬け・しば漬け」のうち、「すぐき漬け」に使われる野菜はどれですか？', '大根', 'きゅうり', 'なす', 'かぶ（すぐき菜）', 3, 'すぐき漬けは「すぐき菜（酸茎菜）」というカブの一種を使った京都独特の乳酸発酵漬物です。上賀茂地区特産の野菜で、独特の酸味と風味が特徴です。乳酸菌を多く含む発酵食品として健康食品としても注目されています。', 2, false),
(3, 6, '「しば漬け（柴漬け）」の発祥の地として知られる京都の地名はどれですか？', '嵯峨', '上賀茂', '大原', '伏見', 2, 'しば漬けは赤しそで色付けしたきゅうり・なす・みょうがなどの漬物で、京都・大原（おおはら）が発祥の地とされています。建礼門院（平清盛の娘・徳子）が大原寂光院に籠った際に里人が献上したのが始まりという伝説があります。', 2, false),
(3, 6, '「壬生菜（みぶな）」はどのような野菜ですか？', 'カブの仲間', '大根の仲間', 'からし菜の突然変異から生まれたからし菜の変種', '九条ねぎの親戚', 2, '壬生菜は京都の壬生地区（中京区）が原産地の伝統京野菜で、からし菜の変種（突然変異）とされます。やや辛みがあり、漬物（壬生菜漬け）や鍋・炒め物に使われます。葉が丸みを帯びているのが特徴です。', 3, false),
(3, 6, '京野菜「海老芋（えびいも）」の特徴として正しいものはどれですか？', '海老の形に似た里芋の一種', '海老の風味がする芋', '海辺でしか育たない芋', '赤色をした芋', 0, '海老芋は里芋の品種で、縞模様と曲がった形が海老に似ていることからこの名がつきました。煮崩れしにくく、煮物（炊き合わせ）によく使われる高級京野菜です。老楊（ろうよ）とも呼ばれます。', 2, false),
(3, 6, '京都府が認定している「京の伝統野菜」は約何品目ありますか？', '約20品目', '約40品目', '約60品目', '約80品目', 1, '京都府が選定している「京の伝統野菜」は約40品目（現在37品目程度）あります。賀茂なす・聖護院かぶ・九条ねぎ・万願寺とうがらし・海老芋・壬生菜・水菜など多彩な伝統野菜が含まれています。', 3, false),
(3, 6, '「水菜（みずな）」が京都の食文化に根付いている理由として最も適切なものはどれですか？', '水辺でのみ育つ珍しい野菜だから', '栄養価が他の野菜より格段に高いから', '江戸時代以前から京都で栽培され、鍋物（ハリハリ鍋など）や漬物に親しまれてきたから', '京都の特殊な土壌でしか育たないから', 2, '水菜（みずな）は京都原産の伝統的な野菜で、江戸時代から栽培されてきました。白菜が普及する前の鍋野菜として「ハリハリ鍋（水菜と鯨肉の鍋）」などで親しまれ、京都の食文化に深く根付いています。', 2, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(4, 7, '祇園祭は何という神社の祭礼ですか？', '北野天満宮', '下鴨神社', '八坂神社', '伏見稲荷大社', 2, '祇園祭は東山区にある八坂神社（やさかじんじゃ）の祭礼です。毎年7月1日から31日まで1ヶ月間にわたって行われる大規模な祭りで、日本を代表する祭りの一つです。', 1, false),
(4, 7, '祇園祭が始まった起源として正しいものはどれですか？', '豊作を願う農業祭として始まった', '疫病退散を祈る御霊会（ごりょうえ）として始まった', '天皇の即位を祝う祭として始まった', '外敵撃退を祈る軍事祭として始まった', 1, '祇園祭の起源は869年（貞観11年）、全国に疫病が流行した際に素戔嗚尊を祀り疫病退散を祈った「祇園御霊会（ぎおんごりょうえ）」です。当時66本の鉾を立てて神泉苑で行われたのが始まりとされています。', 2, false),
(4, 7, '祇園祭の山鉾巡行で、常に先頭を歩く「くじ取らず」の山鉾はどれですか？', '月鉾', '函谷鉾', '長刀鉾', '菊水鉾', 2, '長刀鉾（なぎなたほこ）は祇園祭前祭（さきまつり）山鉾巡行で常に先頭を務める「くじ取らず」の山鉾です。鉾頭に約4mの長刀を飾り、稚児（ちご）が乗って注連縄（しめなわ）切りを行います。', 1, false),
(4, 7, '祇園祭の山鉾巡行は7月に2回行われます。前祭（さきまつり）の巡行日はいつですか？', '7月1日', '7月10日', '7月17日', '7月24日', 2, '前祭（さきまつり）の山鉾巡行は毎年7月17日に行われます。後祭（あとまつり）の巡行は7月24日です。2014年に196年ぶりに後祭が復活し、現在は前祭・後祭の2回の巡行が行われています。', 2, false),
(4, 7, '山鉾巡行における「辻回し（つじまわし）」とは何ですか？', '山鉾が坂道を下るときの操作', '方向転換（直角に曲がる）するための操作', '山鉾が川を渡る儀式', '山鉾に乗る人物を交代させる儀式', 1, '辻回しとは、山鉾巡行のルート上の交差点（辻）で大型の山鉾が直角に方向転換する際の操作です。地面に青竹を敷いてその上に山鉾の車輪を乗せ、縄を引いて少しずつ方向を変えていきます。勇壮な見どころの一つです。', 2, false),
(4, 7, '祇園祭の期間中に行われる「宵山（よいやま）」とは何ですか？', '山鉾巡行の前日に山鉾が夜間ライトアップされる行事', '八坂神社での深夜の神事', '山鉾を解体する日のこと', '神輿が京都を巡行する日', 0, '宵山は山鉾巡行の前日（前祭は7月16日、後祭は7月23日）に行われ、山鉾が夜間にライトアップされます。各山鉾町の会所では展示が公開され、厄除け粽（ちまき）や手拭いなどが販売され、多くの見物客でにぎわいます。', 2, false),
(4, 7, '「祇園祭は日本三大祭りの一つ」とされますが、他の二つとして正しいものはどれですか？', '大阪の天神祭と東京の神田祭', '奈良の春日祭と京都の葵祭', '東京の三社祭と名古屋の山車祭', '博多の祇園山笠と福岡の放生会', 0, '日本三大祭りは「祇園祭（京都）・天神祭（大阪）・神田祭（東京）」が一般的です。なお「日本三大祭り」には諸説あります。京都では葵祭・時代祭・祇園祭が「京都三大祭り」と呼ばれています。', 2, false),
(4, 7, '祇園祭の山鉾を保有する各町が「山鉾町」として伝統を守ってきた地域はどこですか？', '東山区の祇園周辺', '上京区の西陣周辺', '下京区から中京区にかけての旧市街（四条・烏丸周辺）', '伏見区の伏見桃山周辺', 2, '山鉾を保有する「山鉾町」は、下京区から中京区にかけての四条・烏丸周辺の旧市街に集中しています。各町が独自に山鉾を維持管理しており、山鉾の装飾には世界各地から集めた美術工芸品が使われています。', 3, false),
(4, 7, '祇園祭の山鉾に飾られるタペストリー（懸装品）は、どのような産地のものが多く使われていますか？', '国産の西陣織のみ', '中国・朝鮮半島産のものが多く、ヨーロッパ産（ゴブラン織など）もある', '京都・奈良の職人が作ったものだけ', '江戸時代以降に海外から輸入禁止になったため国産のみ', 1, '祇園祭の山鉾に飾られる懸装品（けそうひん）には、中国・朝鮮半島からの渡来品や、ヨーロッパのゴブラン織・インドの染織品なども含まれます。山鉾町が古くから貿易商・商人と関係が深く、貴重な美術品が集まりました。「動く美術館」とも呼ばれます。', 3, false),
(4, 7, '祇園祭の神輿渡御（みこしとぎょ）では、八坂神社のご神体を乗せた神輿が市内を巡行します。神輿は全部で何基ありますか？', '1基', '2基', '3基', '5基', 2, '八坂神社の神輿は3基あります（素戔嗚尊・御息所・八柱御子神の御神霊が乗る3基）。神幸祭（7月17日）に氏子区域を巡行し、還幸祭（7月24日）に八坂神社へ戻ります。', 3, false);
INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES
(5, 8, '金閣寺（鹿苑寺）を建立した室町幕府の将軍は誰ですか？', '足利尊氏', '足利義満', '足利義政', '足利義昭', 1, '金閣寺の金閣（舎利殿）は、室町幕府3代将軍・足利義満（よしみつ）が1397年（応永4年）に建立した北山山荘を起源とします。義満の死後、遺言によって禅寺（鹿苑寺）に改められました。', 1, false),
(5, 8, '金閣（舎利殿）が「金閣」と呼ばれる理由は何ですか？', '夕日が当たると金色に輝くから', '外壁に金箔が貼られているから', '創建者が黄金を収蔵したから', '金を産する地に建てられたから', 1, '金閣（舎利殿）が金閣寺と呼ばれるのは、建物の外壁（第2・第3層）に金箔が貼られているためです。現在の建物は昭和25年（1950年）の放火焼失後、昭和30年（1955年）に再建されたものです。', 1, false),
(5, 8, '金閣（舎利殿）は何層の構造になっていますか？', '2層', '3層', '4層', '5層', 1, '金閣は3層（3階建て）の楼閣建築です。1層は寝殿造り（法水院）、2層は武家造り（潮音洞）、3層は禅宗仏殿造り（究竟頂）と、各層が異なる建築様式で構成されているのが大きな特徴です。', 1, false),
(5, 8, '金閣の最上層（第3層）の屋根に置かれている装飾は何ですか？', '龍', '鳳凰', '鶴', '亀', 1, '金閣の第3層（最上層）の屋根頂上には、金色の銅製の鳳凰（ほうおう）が置かれています。鳳凰は中国・日本で吉兆の象徴とされる伝説の霊鳥で、権威と繁栄を表します。', 2, false),
(5, 8, '金閣寺の正式な寺号はどれですか？', '北山寺', '金閣寺', '鹿苑寺（ろくおんじ）', '相国寺別院', 2, '金閣寺の正式名称は「鹿苑寺（ろくおんじ）」、山号は「北山（ほくざん）」です。「金閣寺」は通称で、建物（金閣）の名称が寺院全体の呼び名として定着しました。臨済宗相国寺派の寺院です。', 2, false),
(5, 8, '金閣寺が世界遺産に登録されたのはいつですか？', '1987年', '1994年', '2000年', '2007年', 1, '金閣寺は1994年（平成6年）に「古都京都の文化財」の一つとしてユネスコ世界文化遺産に登録されました。京都・宇治・大津の17の文化財が一括して登録されています。', 1, false),
(5, 8, '金閣の前に広がる池の名前はどれですか？', '大沢池', '曹源池', '鏡湖池（きょうこち）', '鏡容池', 2, '金閣の前には「鏡湖池（きょうこち）」という池が広がっており、金閣が池に映る姿は絶景として知られています。池には芦山島など小島が浮かんでいます。', 2, false),
(5, 8, '現在の金閣はいつ再建されましたか？', '昭和25年（1950年）', '昭和30年（1955年）', '昭和40年（1965年）', '平成7年（1995年）', 1, '金閣は昭和25年（1950年）7月2日に当時の修行僧による放火で焼失しました。この事件は三島由紀夫の小説「金閣寺」のモチーフにもなっています。現在の金閣は昭和30年（1955年）に再建されたものです。', 2, false),
(5, 8, '金閣寺の庭園は何という形式の庭園ですか？', '枯山水庭園', '池泉回遊式庭園', '露地（茶庭）', '整形式庭園', 1, '金閣寺の庭園は「池泉回遊式庭園（ちせんかいゆうしきていえん）」です。鏡湖池を中心に、複数の島や石組みを配し、周囲を歩きながら楽しめる庭園形式です。国の特別史跡・特別名勝に指定されています。', 2, false),
(5, 8, '金閣寺（鹿苑寺）は現在どの宗派に属していますか？', '天台宗', '真言宗', '臨済宗相国寺派', '浄土宗', 2, '金閣寺（鹿苑寺）は臨済宗相国寺派の寺院です。相国寺（上京区）の山外塔頭として位置づけられています。禅宗の一派である臨済宗は、鎌倉・室町時代の武家文化と深く結びついています。', 3, false);
